from book import Chapter
c=Chapter('06')
c.add('''人与人为什么能够合作？看起来，这个问题的答案很简单：因为合作对双方有好处。可是，只要多想一步，就会遇到困难。如果一个人拿走了好处，却不履行自己的承诺，另一个人怎么办？如果为了防止背叛，双方都先把最坏的打算做好，原本可能的合作又怎样开始？

更复杂的是，即使一段合作已经形成，它也未必会永远保持原来的样子。有人逐渐掌握更多资源，有人越来越依赖对方；最初可以平等商量的事情，后来可能变成只能接受的条件。因此，研究社会组织，不能只看某一时刻的规则，还要看规则在反复互动中会把人与人的关系推向哪里。''')
c.heading('从原子之间的结合，理解人之间的联系')
c.src('ORIGINAL',71,replacements=[('（极限/余极限结构）',''),('其过程遵循能量最小化原则，最终在量子力学规则的约束下达到稳定的不动点状态','其结构和变化受物理规律、环境条件与相互作用共同约束')])
c.src('ORIGINAL',72,replacements=[('最简单的连接','一种基本的连接'),('这个过程同样遵循不动点原理和路径/结构最小化原理，在博弈论中，这对应的正是','我希望从稳定结构怎样形成的角度理解这个过程。在博弈论中，可以借助两个概念来区分不同的问题：'),('一种资源分配上的“能量最小化”状态','一种资源分配上的状态')])
c.add('''这两个概念不能混成一个。“没有人能够单方面改变策略而获益”，不等于大家已经处在最好的处境。两个人因为互不信任而各自防范，可能谁也不敢先放下防备，双方却都在为此付出代价。稳定说明这种关系能够维持，是否值得维持，还要看它使什么人得到什么，又让什么人失去了什么。

因此，我关心的不只是怎样形成稳定组织，还包括怎样让组织保留通向更好状态的可能。一个永远不改变的结构可以很稳定，但这种稳定也可能使它丧失适应新情况的能力。''')
c.src('META-THEORY',177,start='如果拿人类社会和物理世界来对比',replacements=[('人类之间通过以牙还牙策略','人类之间可以通过以牙还牙一类策略'),('这就像于','这就像'),('得失、共用或电子','得失或共用电子'),('是人类社会构造的基本反应','是我考察人类社会构造的一种基本反馈机制'),('无论在哪个一个层级上，哪个一个具体的结构上，都会出现','在不同层级、不同具体结构上，都可以考察是否出现'),('其中参与的个人之间，都会存在','其中参与的个人之间，常能观察到'),('就像在物理学和范畴论中，当对称性无所不在时，那么对称性就是这个学科的最基本原理之一，并参与了所有高级性质的构造和产生。','一种关系如果反复出现在不同层级中，就值得继续追问它是不是参与了这些结构形成的共同机制。')],note='混合对话中第177段的作者发言，选取化学键与社会联系的完整论证')
c.add('''所谓以牙还牙，最简单的形式，是先选择合作，之后依据对方的行为调整自己的回应。对方合作，就继续合作；对方背叛，就作出相应反应。重复博弈中的合作研究，使这种看起来朴素的策略成为一个值得认真考察的机制。但它能取得什么结果，仍然与相遇机会、收益、误判和对方的策略有关。[Axelrod 与 Hamilton 的合作演化研究](https://pubmed.ncbi.nlm.nih.gov/7466396/)

实际的人类关系比一个简单模型丰富得多。同样是发现对方没有履行承诺，有人会立即停止合作，有人会先询问原因；有人惩罚一次就愿意恢复往来，有人会把这件事情记很久。差别不只是“惩罚”与“不惩罚”，而是一整套反应强度、持续时间和恢复条件。''')
c.heading('强硬与温和，是怎样形成的')
c.src('META-THEORY',16,start='当然这种策略类型的分割并不是严格数学意义上的静态离散对象',end='一个概念划分而已。',replacements=[('当然这种','这种'),('是像maoa基因型可能是多种重复序列模式的集合中的一个一样，是一个','可以理解为一个')])
c.src('R54626',33,end='倾向强硬和温和的概率？',replacements=[('很简单的道理，maoa-h和maoa-l不同基因的人','可以把问题拆成几步来问：具有不同遗传和生理条件的人'),('这些受基因影响的情绪因素','这些可能受到基因、发育和生活经历影响的情绪因素')])
c.add('''这样提问，是因为从底层结构到高层行为，中间隔着许多环节。我们不能只看到最后一次争执，就认为一个人天生属于某种永远不变的阵营；也不能因为行为受环境影响，就反过来断言生理差异完全不重要。

以 MAOA 为例，已有研究考察过基因型与受到挑衅后的惩罚行为之间的联系，观察到的差异依赖具体实验条件。这样的结果使“个体差异怎样进入互动过程”成为可以研究的问题，但不能直接给某个人、某个群体或某种政治制度作出基因判定。[McDermott 等人的实验研究](https://pmc.ncbi.nlm.nih.gov/articles/PMC2650118/)

对这套框架来说，重要的是把每一层之间的关系展开：低层的变化怎样影响反应，反应怎样影响策略，策略又怎样在环境中获得奖励或遭遇失败。究竟哪个变量在什么条件下起主要作用，需要在这些关系中考察。''')
c.src('META-THEORY',47,start='但是我对遗传DNA层面的结构差异',replacements=[('但是我对遗传DNA层面的结构差异','对于遗传 DNA 层面的结构差异'),('这个结论是有直觉上的肯定的','这条可能的因果路径，我有直觉上的肯定，也希望把它逐层研究清楚'),('其实这也是我处于第一性原理的思考','这也是我从第一性原理出发的思考'),('如果我们通过这样一个低阶范畴中的构造，会影响高阶范畴中对象的性质的理论','如果我们能够研究清楚低阶结构怎样影响高阶对象的性质'),('其实是来源于低阶结构中一个很小的结构差异','可能包含低阶结构中很小差异经过多层作用和反馈而产生的影响')])
c.src('META-THEORY',83,start='就像人类心理和文学上',end='构造的好，可以实现最优组合。',replacements=[('红色的快乐','红色是快乐的'),('并不是由某个单一因素导致的','并不是由某个单一因素必然决定的'),('最大化优化高阶对象的属性','尝试改善高阶对象的属性'),('任何一个低阶对象的性质，其实没有好坏之分','不能把一个低阶参数直接标成道德意义上的好或坏'),('构造的好，可以实现最优组合','通过不同的组合，可以产生不同的高阶结果')])
c.heading('一个博弈模型没有写出的因素，并不等于不存在')
c.src('R54626',25,start='所谓Maynard Smith 的鹰鸽博弈',replacements=[('所谓Maynard Smith 的鹰鸽博弈，并不是一个数学定理和原理，是一个数据实验模型，其实验对象就是博弈中的人类对象，而基因就是这些人类对象行为的内部重要因素之一','以 Maynard Smith 的鹰鸽博弈模型为例，其中的数学结论依赖模型的假设。而当我们用它来考察现实个体时，遗传、生理和生活经历又是这些个体行为的影响因素'),('这个模型只能说明鹰派和鸽派是在反复博弈中逐渐形成的','模型可以帮助我们分析不同策略在反复博弈中的变化'),('恰恰相反，这个数学模型中根本没有考虑到这个因素，并不是这个因素对鹰派和鸽派的形成没有任何影响','如果一种模型没有显式区分这个因素，就不能仅凭这一点，断言这个因素在现实中没有任何影响')])
c.add('''反过来也一样。知道一个变量可能重要，并不意味着它已经解释了全部现象。同一种倾向，在不同环境中可能被放大，也可能被抑制。模型的工作，就是把这些因素分开，让我们看见改变一个条件之后，结果会不会随之改变。

例如，两个人都容易在受挫时激动，但一个人所处的环境鼓励立即报复，另一个人的环境允许澄清误会、恢复合作，他们在长期互动中形成的行为可能很不一样。把差异全部归结为基因，会漏掉环境；把差异全部归结为制度，也可能漏掉个体。''')
c.src('R54626',47,replacements=[('这就是我说的决定分化的另一个因素，就是','决定分化的另一个因素，是'),('那么按照最大化最小化原理，人们总是倾向于采用成本最小的方式来解决冲突，而权力差巨大的稳定威权体系中，管制压制和暴力镇压是成本最小的方式','那么从行动者所面对的成本来看，如果管制、压制和暴力镇压对掌握权力的人来说成本较低'),('于是人与人之间解决背叛的策略都会倾向于','就会鼓励人们在有能力这样做时倾向于'),('所以人们越是倾向于使用它','人们就更容易继续使用它'),('反之，在一个民主制度的环境中，暴力镇压反倒是成本更高的方式','反过来，在一个能够约束任意暴力、提供沟通和申诉渠道的制度环境中，暴力压制反倒可能是成本更高的方式'),('也会分裂成鹰派和鸽派阵营','也可能分化出相对强硬和相对温和的倾向'),('都倾向于使用强硬手段','普遍倾向于使用强硬手段')])
c.heading('为什么一次成功，会改变下一次选择')
c.src('META-THEORY',264,start='举个例子，我们知道基于最小化原理',end='这是个决策中理性思考部分的收敛过程',replacements=[('举个例子，我们知道基于最小化原理，人们总是倾向于采用最小代价的手段来解决分歧和消除问题','举个例子，假定人们倾向于采用自己看来代价较小的手段，来解决分歧和消除问题'),('暴力镇压会是成本最小的解决问题方式','暴力镇压可能成为上位者眼中成本较小的解决方式'),('所以会导致人们倾向于采用暴力手段来解决问题','就会鼓励有能力这样做的人采用暴力手段解决问题'),('这是个决策中理性思考部分的收敛过程','这就是一个行动者的局部选择，在反复反馈中推动整个结构收敛的简化过程')])
c.add('''注意，这里说的“成本低”，必须问清楚是对谁低。压制者可能只付出一项命令的成本，被压制者却承担了巨大的损失。如果记录和决策只看前者，这种方式就会显得有效；如果把受影响者的损失、后续反抗以及社会内部的防范成本一起计算，结果就可能很不一样。

这也解释了为什么一个结构能够稳定存在，并不能证明它已经使所有人受益。局部的成功可以使一条路径越走越熟，甚至使参与者很难想象别的可能。新机制要改变的，是这种反馈的组织方式，而不只是把原来坐在某个位置上的人换掉。''')
c.src('META-THEORY',219,start='奖惩机制其实就是一个评价函数',end='整个人类文明进化能力高低的根本因素。',replacements=[('它会让这个过程趋向于收敛或发散，而不是随机的震荡','它可以使关系在反复互动中加强或减弱，形成有方向的反馈'),('这样能够让符合评价函数的结构趋于收敛','在相应条件下，可以让符合评价函数的结构趋于收敛'),('是整个人类文明进化能力高低的根本因素','是影响整个人类文明进化能力的重要问题')])
c.heading('保留差异，为什么可能比消灭差异更有力量')
c.src('META-THEORY',264,start='当然可以把“文明的进化能力”作为一个评价标准来看待',end='每一个进化方向都是有价值的，它的价值就在于丰富了进化空间，为下一个进化的涌现做准备。',replacements=[('就像在我们一起进行的hotpath项目中','就像在软件开发中'),('某个benchmark看作一个hotpath的评价标准','一项性能测试看作某条程序路径的评价标准'),('这个hotpath存在的价值','这条程序路径存在的全部价值'),('事实上，所有存在的，都是合理的，都是某个最小化收敛过程涌现的不动点对象','事实上，能够形成并存在的结构，总有它形成的条件，不能只用一个指标穷尽它的意义'),('人类DNA基因中也有很多休眠的不再激活的陈旧基因片段，你也不应该说激活的DNA片段价值更高','一个暂时没有被使用的结构，也不能仅凭这一点被断定为没有价值'),('如果要说的话，存在即合理，一旦存在就不会消失，只会增加整个系统的多样性，并且会推进这个具有进化能力的无限高阶范畴系统的进一步涌现和进化','不同结构的存在，丰富了系统可以继续组合的材料，也可能为后续的涌现和进化提供条件'),('每一个进化方向都是有价值的，它的价值就在于丰富了进化空间','不同的进化方向可能具有不同的价值，其中一项就是丰富进化空间')])
c.src('SEED-H1-0',0,end='而且温和以牙还牙策略能够更好的保证多样性。',replacements=[('是的。',''),('而且温和以牙还牙策略能够更好的保证多样性','温和的回应、恢复合作的机会，也更有利于保留这种多样性')])
c.src('SEED-H1-0',0,start='有的时候即使某一项技术能耗比远远领先',end='反而能够在危机时发挥作用。')
c.add('''因而，选择更好的实现，与把所有其他实现全部抹掉，不应该成为同一件事。我们可以在常见情况下采用效率更高的方式，同时保留那些在少数条件下仍然有用的结构。一个组织能够接受不同经验和异议，也就保留了在环境改变时重新组合的材料。

这里的多样性也包括我们不喜欢、暂时不能理解的想法。讨论一个想法，需要尽量把它真正主张的内容说明白；不能先把它改写成最容易反对的版本，再宣布已经解决了问题。否则，看起来热闹的争论，仍然只是旧有立场的互相加固。''')
c.heading('理解冲突的形成，并不等于放任伤害')
c.src('R54626',56,start='我的本意是',replacements=[('我的本意是','我的主张是'),('这个元认知，就是我前面提到的：','这个元认知可以这样表达：'),('低阶层层面','低阶层面'),('这些差异都可以从科学理论上构建出可重现的因果链解释','对这些差异，我们应当尝试从科学理论上研究其形成条件，构建可以检验的因果解释'),('“人类所有','人类所有')])
c.add('''有人会问，理解伤害行为的成因，会不会削弱对受害者的保护？这两件事并不需要互相排斥。面对正在发生的伤害，需要保护受影响的人；为了减少下一次伤害，又需要研究它为什么会反复发生。如果只处理已经出现的行为，却始终不触及形成这种行为的条件，社会就会不断重复同一种冲突。

我的出发点，是希望解释能够打开改变的可能。一个现象只要被定义成不可理解、不可改变的邪恶，人们就很容易只剩下消灭对象这一种想象。把它放回形成条件和反馈过程之中，才有可能寻找更有效、代价更小的预防方式。''')
c.src('R54626',65,start='我的本意就是希望新的元认知',replacements=[('我的本意就是希望新的元认知，能够小数所有人类脑海中和人之中认为原本那种激进的宗教情结式的恶魔和邪恶观点','我希望这种元认知，能够减少人们认知中那种激进的、宗教情结式的恶魔和邪恶观点'),('让宗教道德的狂热情绪绑，你就强烈倾向于','如果被宗教道德的狂热情绪支配，人们就容易倾向于'),('其原理的化','其原理的话')])
c.add('''“把犯罪看作疾病”在这里表达的是一种研究和预防的态度：把形成伤害的现象当作可以研究、可以修正的问题。它不能被反过来用作给不同意见贴病名的理由，更不能跳过对具体行为和条件的理解，重新把人分成天生应该被排除的类别。否则，解释的词语虽然换了，原来的二分结构却仍然存在。

从这里可以看见，这套理论对社会组织的要求，并不是先找到一群完全没有差异的人。它恰恰从差异出发，研究怎样让差异形成更丰富的联系，让错误可以得到反馈，让参与者不必在一次冲突后失去所有恢复合作的可能。要做到这一点，还需要新的物质条件、新的知识工具，以及能够让更多人真正平等参与的能力基础。''')
